module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus("connecting", "Connecting to ProPresenter 7 API...");
    },
    onTransportReady: function(transport, config) {
        engine.setStatus("connected", "ProPresenter 7 Ready");
    },
    onAction: function(transport, actionId, params) {
        if (actionId === "propresenter_get_active_slide" || actionId === "get_active_slide" || actionId === "get_status") {
            return engine.http.get("/v1/presentation/active").then(function(res) {
                if (res.json && res.json.presentation && res.json.presentation.slide_index !== undefined) {
                    engine.setVariable("current_slide", String(res.json.presentation.slide_index));
                }
                return "Queried Active Slide";
            });
        }
        if (actionId === "pp7_next" || actionId === "next_slide") {
            return engine.http.get("/v1/presentation/active/next").then(function(res) {
                return "Triggered Next Slide";
            });
        }
        if (actionId === "pp7_prev" || actionId === "prev_slide") {
            return engine.http.get("/v1/presentation/active/previous").then(function(res) {
                return "Triggered Previous Slide";
            });
        }
        if (actionId === "pp7_clear_all" || actionId === "clear_all") {
            return engine.http.get("/v1/clear/all").then(function(res) {
                return "Cleared All Layers";
            });
        }
        return "ProPresenter Action Executed";
    }
};
